#include <functional>
#include <utility>
#include <vector>

template <class T, class Less>
void mergeSortRange(std::vector<T>& a, std::vector<T>& buffer, std::size_t lo, std::size_t hi, Less& less)
{
    if (hi - lo < 2) return;
    std::size_t mid = lo + (hi - lo) / 2;
    mergeSortRange(a, buffer, lo, mid, less);
    mergeSortRange(a, buffer, mid, hi, less);
    std::size_t i = lo, j = mid, k = lo;
    while (i < mid && j < hi) buffer[k++] = less(a[j], a[i]) ? std::move(a[j++]) : std::move(a[i++]);
    while (i < mid) buffer[k++] = std::move(a[i++]);
    while (j < hi) buffer[k++] = std::move(a[j++]);
    for (k = lo; k < hi; ++k) a[k] = std::move(buffer[k]);
}

template <class T, class Less = std::less<T>>
void mergeSort(std::vector<T>& a, Less less = Less{})
{
    std::vector<T> buffer(a.size());
    mergeSortRange(a, buffer, 0, a.size(), less);
}

static long long countRange(std::vector<int>& a, std::vector<int>& buf, std::size_t lo, std::size_t hi)
{
    if (hi - lo < 2) return 0;
    std::size_t mid = lo + (hi - lo) / 2;
    long long count = countRange(a, buf, lo, mid) + countRange(a, buf, mid, hi);
    std::size_t i = lo, j = mid, k = lo;
    while (i < mid && j < hi)
    {
        if (a[j] < a[i])
        {
            count += static_cast<long long>(mid - i);
            buf[k++] = a[j++];
        }
        else buf[k++] = a[i++];
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi) buf[k++] = a[j++];
    for (k = lo; k < hi; ++k) a[k] = buf[k];
    return count;
}

long long countInversions(std::vector<int> a)
{
    std::vector<int> buf(a.size());
    return countRange(a, buf, 0, a.size());
}

static std::vector<int> mergeTwo(const std::vector<int>& a, const std::vector<int>& b)
{
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) out.push_back(b[j] < a[i] ? b[j++] : a[i++]);
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

std::vector<int> mergeAll(const std::vector<std::vector<int>>& lists)
{
    if (lists.empty()) return {};
    std::vector<std::vector<int>> round = lists;
    while (round.size() > 1)
    {
        std::vector<std::vector<int>> next;
        for (std::size_t i = 0; i + 1 < round.size(); i += 2) next.push_back(mergeTwo(round[i], round[i + 1]));
        if (round.size() % 2 == 1) next.push_back(std::move(round.back()));
        round = std::move(next);
    }
    return round[0];
}

