#include <string>

struct Rec { int key; int order; };

TEST("merge sort") {
    std::vector<int> a{ 38, 27, 43, 3, 9, 82, 10, 3 };
    mergeSort(a);
    CHECK_EQ(a, (std::vector<int>{ 3, 3, 9, 10, 27, 38, 43, 82 }));
    std::vector<std::string> w{ "kiwi", "fig", "apple", "date" };
    mergeSort(w, std::greater<std::string>{});
    CHECK_EQ(w, (std::vector<std::string>{ "kiwi", "fig", "date", "apple" }));
    std::vector<int> e;
    mergeSort(e);
    CHECK(e.empty());
}
TEST("merge sort is stable") {
    std::vector<Rec> r;
    for (int i = 0; i < 1000; ++i) r.push_back({ (i * 37) % 10, i });
    mergeSort(r, [](const Rec& a, const Rec& b) { return a.key < b.key; });
    bool ok = true;
    for (std::size_t i = 1; i < r.size(); ++i)
        ok = ok && (r[i - 1].key < r[i].key || (r[i - 1].key == r[i].key && r[i - 1].order < r[i].order));
    CHECK(ok);
}
TEST("merge sort of 100,000 values") {
    std::vector<int> a(100000);
    for (int i = 0; i < 100000; ++i) a[i] = (i * 7919) % 100003;
    mergeSort(a);
    bool sorted = true;
    for (std::size_t i = 1; i < a.size(); ++i) sorted = sorted && a[i - 1] <= a[i];
    CHECK(sorted);
}
TEST("counting inversions") {
    CHECK_EQ(countInversions({ 2, 4, 1, 3, 5 }), 3LL);
    CHECK_EQ(countInversions({ 1, 2, 3 }), 0LL);
    CHECK_EQ(countInversions({ 3, 3, 3 }), 0LL);
    CHECK_EQ(countInversions({}), 0LL);
    CHECK_EQ(countInversions({ 8, 3, 9, 1, 1, 7, 2, 6, 6, 0 }), 28LL);
}
TEST("inversions of 100,000 values") {
    std::vector<int> rev(100000);
    for (int i = 0; i < 100000; ++i) rev[i] = 100000 - i;
    CHECK_EQ(countInversions(rev), 4999950000LL);
    std::vector<int> a(100000);
    for (int i = 0; i < 100000; ++i) a[i] = i % 2 == 0 ? i : -i;   // 0, -1, 2, -3, ...
    CHECK_EQ(countInversions(a), 2500000000LL);
}
TEST("merging many lists") {
    CHECK_EQ(mergeAll({ { 1, 4, 7 }, { 2, 5, 8 }, { 3, 6, 9 } }), (std::vector<int>{ 1, 2, 3, 4, 5, 6, 7, 8, 9 }));
    CHECK_EQ(mergeAll({ {}, { 5 }, {}, { 1, 9 } }), (std::vector<int>{ 1, 5, 9 }));
    CHECK(mergeAll({}).empty());
    std::vector<std::vector<int>> many(1000);
    for (int i = 0; i < 100000; ++i) many[i % 1000].push_back(i);
    std::vector<int> all = mergeAll(many);
    bool ok = all.size() == 100000;
    for (int i = 0; ok && i < 100000; ++i) ok = all[i] == i;
    CHECK(ok);
}

